pub(crate) fn infer_followup_agent_and_workspace(path: &Path) -> (Option<String>, Option<String>) {
    let path_str = path.to_string_lossy();
    let path_lower = path_str.to_ascii_lowercase().replace('\\', "/");

    let agent_name = if crate::connectors::omp::owns_session_path(path) {
        Some("omp".to_string())
    } else {
        [
            (".local/share/opencode", "opencode"),
            ("sourcegraph.amp", "amp"),
            (".local/share/amp", "amp"),
            (".config/gh-copilot", "copilot"),
            (".config/gh/copilot", "copilot"),
            ("github-copilot", "copilot"),
            (".copilot", "copilot"),
            (".pi/agent", "pi_agent"),
            (".openclaw", "openclaw"),
            ("clawdbot", "clawdbot"),
            ("cline", "cline"),
            (".aider", "aider"),
            (".claude", "claude_code"),
            (".codex", "codex"),
            ("cursor", "cursor"),
            (".config/gemini", "gemini"),
            (".gemini", "gemini"),
            (".vibe", "vibe"),
        ]
        .into_iter()
        .find_map(|(marker, slug)| path_lower.contains(marker).then(|| slug.to_string()))
    };

    let workspace = path.parent().map(|parent| parent.display().to_string());
    (agent_name, workspace)
}


